  "sources": [
    {
      "id": "fiction_library_official_zh",
      "document_name": "AI虚构教学材料：澄湾图书馆工作简报",
      "page": null,
      "text": "以下城镇、人物、机构及事件均为AI自编虚构教学设定，不是真实历史记录。澄湾镇图书馆在试行记录中写道：原有工作人员通过调整排班，每周增加两个晚间开放时段，试行期间不增加人员预算。简报将目的表述为方便白天上班的读者，并称晚间常能见到以前较少来馆的人。简报没有提供总到访人数、读者职业分布或试行前后的完整对照，也没有说明其他服务时段是否减少。该简报面向管理部门汇报试行工作，不能自动视为全部读者体验的代表。",
      "document_id": "fixture-doc-140925271d63946d182b1933"
    },
    {
      "id": "fiction_library_readers_zh",
      "document_name": "AI虚构教学材料：两位读者的回忆片段",
      "page": null,
      "text": "以下访谈是为课堂构造的虚构文本，不是真人证言。读者甲回忆：我在商店轮晚班，新增的开放时间并不总与我的下班时间吻合，但邻居说她终于能下班后借书。读者乙回忆：我傍晚常在馆里备课，延时开放后更愿意留下来；不过我记得部分白天时段的咨询台没有以前方便。两人都未记录准确日期，也没有全馆排班表。片段能够提供不同位置的体验和进一步调查的问题，不能据此直接估算全镇受益比例，或证明工作人员有特定隐藏动机。",
      "document_id": "fixture-doc-faa6ccf7c69ca21b54a089e0"
    },
    {
      "id": "fiction_library_method_zh",
      "document_name": "AI自编教学说明：比较材料与限定结论",
      "page": null,
      "text": "比较史料时，先区分材料直接声称了什么与研究者据此推断了什么，再考虑作者位置、受众、写作时间与目的。立场不等于材料无价值；官方简报和个人回忆都可能真实呈现局部经验，同时有所省略。互相支持的片段可增强一个有限解释，表面冲突也可能来自不同群体、时段或观察尺度。可论证延时开放扩大了某些人的使用机会，也可论证它是在预算约束下重新分配便利，两者不必完全排斥。好的回答应明确自己的判断、至少比较两种材料、正面处理一种替代解释，并说明哪些更强结论尚缺证据；不能把受益体验直接升级为全体受益，也不能把局限直接升级为政策完全失败。",
      "document_id": "fixture-doc-3869a5adcaa63e53cc5777ea"
    }
  ]
}

